import{buildArtery,buildCancer}from './health-meshes.js?v=20261023-physicscomplete01';
import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';
import{arteryStates,depositAt,treatments,diseaseLinks,riskCases,scatterPoints,tumourState}from './health-models.js?v=20261023-physicscomplete01';
const svg=(body,label)=>`<svg class="shell-diagram health-diagram" viewBox="0 0 540 350" role="img" aria-label="${label}"><defs><linearGradient id="healthWall"><stop stop-color="#e8b4a1"/><stop offset="1" stop-color="#b56159"/></linearGradient></defs>${body}</svg>`;
const txt=(x,y,t,size=16,anchor='middle')=>`<text x="${x}" y="${y}" fill="#f8f6f2" font-size="${size}" text-anchor="${anchor}">${t}</text>`;
export function arteryFigure(state='narrow',deposit){let s=arteryStates[state]||arteryStates.narrow,d=deposit??s.deposit,r=state==='stent'?66:90*(1-d);return svg(`<path d="M70 105H465V265H70Z" fill="url(#healthWall)"/><path d="M70 120Q267 ${120+d*115} 465 120V250Q267 ${250-d*115} 70 250Z" fill="#d8b578"/><path d="M70 ${185-r*.65}Q267 ${185-r*.45} 465 ${185-r*.65}V${185+r*.65}Q267 ${185+r*.45} 70 ${185+r*.65}Z" fill="#824946"/>${state==='stent'?Array.from({length:12},(_,i)=>`<path d="M${130+i*23} 143l20 84m-20 0l20-84" stroke="#d5e2e7" stroke-width="3"/>`).join(''):''}<path d="M110 186H410l-15-9m15 9l-15 9" stroke="#f8e3c4" stroke-width="4" fill="none"/>${txt(270,55,state==='healthy'?'Open artery':state==='stent'?'Supported lumen':'Fatty deposits narrow the lumen',21)}${txt(270,304,'Blood → heart muscle',18)}${txt(270,332,'Cutaway · symbolic widths · no measured flow',13)}`,`Artery cutaway: ${state}; blood passes through the remaining lumen`);}
export function cancerFigure(kind='benign',step=3){const s=tumourState(kind,step),cells=Array.from({length:s.count},(_,i)=>{let a=i*2.4,r=11*Math.sqrt(i),x=180+Math.cos(a)*r,y=175+Math.sin(a)*r;return`<circle cx="${x}" cy="${y}" r="13" fill="${kind==='normal'?'#7d9fa8':'#db8a79'}" stroke="#f2d0bd"/><circle cx="${x-2}" cy="${y}" r="4" fill="#824945"/>`;}).join('');return svg(`<rect x="35" y="55" width="300" height="245" rx="25" fill="#ffffff08" stroke="#d5dfe5" stroke-dasharray="${s.invasion?'8 12':'0'}"/>${cells}${s.invasion?'<circle cx="347" cy="196" r="14" fill="#db8a79"/>':''}<path d="M390 70V285" stroke="#9c6362" stroke-width="34"/>${s.inBlood?'<circle cx="390" cy="190" r="10" fill="#e8bda4"/>':''}${s.secondary?'<g fill="#db8a79"><circle cx="474" cy="235" r="17"/><circle cx="492" cy="255" r="17"/><circle cx="466" cy="266" r="17"/></g>':''}${txt(180,32,kind==='normal'?'Regulated population':kind==='benign'?'Contained abnormal growth':'Invasion & spread',20)}${txt(170,328,'Primary tissue',14)}${txt(391,328,'Blood',14)}${s.secondary?txt(480,304,'Secondary',13):''}`,`${kind} cell model at step ${step}: ${s.secondary?'secondary growth':s.inBlood?'cells in blood':s.invasion?'invasion':'contained population'}`);}
function networkFigure(from,to,revealed,caption=''){return `<div class="health-network"><div class="health-node">${from}</div><span aria-hidden="true">↓</span><div class="health-node ${revealed?'active':''}">${revealed?to:'Predict the effect'}</div>${caption?`<p>${caption}</p>`:''}</div>`;}
export function plotFigure(type,w={}){let body='<path d="M65 35V285H505" stroke="#bdcdd7" stroke-width="2" fill="none"/>';
if(type==='hist'){const bars=w.bars||[0,0,0];for(let i=0;i<3;i++)body+=`<rect x="${80+i*125}" y="${285-Math.max(0,Math.min(12,Number(bars[i])||0))*17.5}" width="125" height="${Math.max(0,Math.min(12,Number(bars[i])||0))*17.5}" fill="#d98c7d" stroke="#f4d4c2"/>`;for(let i=0;i<=12;i+=2)body+=txt(52,290-i*17.5,i,13,'end');for(let i=0;i<4;i++)body+=txt(80+i*125,309,i*4,13);body+=txt(270,342,'Illness duration / hours',16)+txt(155,24,'Frequency',16);}
else if(type==='rates'){for(let i=0;i<2;i++){let v=Math.max(0,Math.min(12,Number(w.rates?.[i])||0));body+=`<rect x="${150+i*180}" y="${285-v*20}" width="80" height="${v*20}" fill="#d98c7d"/>`+txt(190+i*180,309,['A','B'][i],15);}for(let i=0;i<=12;i+=2)body+=txt(52,290-i*20,i,13,'end');body+=txt(270,342,'Region · same one-year period',15)+txt(230,24,'New cases / population (%)',16);}
else {for(let x=0;x<=40;x+=10)body+=txt(65+x*10,309,x,13);for(let y=0;y<=100;y+=20)body+=txt(52,290-y*2.3,y,13,'end');let points=w.points||scatterPoints;points.forEach(([x,y],i)=>{body+=`<circle cx="${65+x*10}" cy="${285-y*2.3}" r="6" fill="#efb794"/>`+txt(76+x*10,281-y*2.3,String(i+1),12,'start');});body+=txt(280,342,'Adults smoking / %',16)+txt(275,24,'New lung cases / 100,000 / year',15);}
return svg(body,'Original teaching '+type+' plot; exact observations and plotted values are provided in the activity').replace('health-diagram','health-diagram health-plot');}
export function showHealth(spec='artery:narrow',w={}){let[kind,variant]=spec.split(':');const note='<p class="diagram-caption">Original teaching model · symbolic sizes, steps and values.</p>';
if(kind==='artery'||kind==='statin'){const state=kind==='statin'?'narrow':variant||'narrow',deposit=kind==='statin'?depositAt(w.step??3,w.statin===true):undefined;renderCustomModel({name:kind==='statin'?'Slow the build-up':state==='stent'?'Hold the lumen open':'Inside a coronary artery',formula:kind==='statin'?(w.statin?'With statin effect':'Without statin effect'):arteryStates[state].oxygen,aria:'Coronary artery cutaway: '+state+'. Blood cells in the lumen; symbolic width, not measured flow.',kicker:'SCHEMATIC ARTERY CUTAWAY',atoms:[],bonds:[],radius:2.6,viewKey:'health-artery',startPaused:true,note:'Symbolic geometry · not a blood-flow or treatment forecast',diagram:arteryFigure(state,deposit)+note,build:(g,T)=>buildArtery(g,T,state,deposit)});return;}
if(kind==='cancer'){let type=variant||w.kind||'benign',step=w.step??3;renderCustomModel({name:type==='normal'?'Regulated cells':type==='benign'?'Contained growth':'Across the tissue boundary',formula:type==='malignant'?'Invasion → blood → secondary growth':'Containment and division control',aria:type+' tissue model, step '+step+'. Primary tissue, boundary and blood vessel; symbolic cells.',kicker:'SCHEMATIC TISSUE CUTAWAY',atoms:[],bonds:[],radius:2.65,viewKey:'health-cancer',startPaused:true,note:'Symbolic cells · steps are not real time or diagnostic evidence',diagram:cancerFigure(type,step)+note,build:(g,T)=>buildCancer(g,T,type,step)});return;}
let title,formula,figure;
if(kind==='links'){let d=diseaseLinks.find(x=>x.id===variant)||diseaseLinks[0];title='Connect the conditions';formula='A possible pathway, not an inevitable outcome';figure=networkFigure(d.from,d.to,w.revealed!==false,w.revealed===false?'':d.mechanism);}
else if(kind==='wellbeing'){title='Two dimensions of health';formula='Physical + mental wellbeing';const explanations={Diet:'Nutrient and energy supply can influence body function and wellbeing.',Stress:'Stress can affect sleep, mental wellbeing and physical functioning.','Life situations':'Housing, caring demands and access to food or care can influence wellbeing.'};figure=networkFigure(w.factor||'Diet · stress · life situations','Physical and mental wellbeing',true,explanations[w.factor]||'Diseases and circumstances can interact.');}
else if(kind==='multiple'){title='Several influences can interact';formula='No personal probability is calculated';figure=networkFigure(w.factor||'Smoking exposure','Cardiovascular disease risk',true,'Compare explanations without adding risk factors into a made-up score.');}
else if(kind==='risks'){let r=riskCases.find(x=>x.id===(variant||w.risk))||riskCases[0];title='Follow a risk factor';formula='Increased risk ≠ certainty';figure=networkFigure(r.name,r.effect,w.revealed!==false,w.revealed===false?'':r.mechanism);}
else if(kind==='costs'){title='Who bears the cost?';formula='Human and financial effects';figure=networkFigure(w.level||'Individual → community → nation → world','Wellbeing, care, work and resources',true,'A cost can affect more than one level.');}
else if(kind==='treatments'){let t=treatments.find(x=>x.id===w.treatment)||treatments[0];title='Weigh benefit against limitation';formula=t.name;figure=`<div class="health-network"><div class="health-node">${t.name}</div><div class="health-node active">${t.benefit}</div><div class="health-node">${t.risk}</div></div>`;}
else {title='Investigate the evidence';formula='Original illustrative dataset';figure=variant==='sample'?networkFigure('Target population','Representative sample',true,'Size, selection, age and non-response all matter.'):plotFigure(variant||'scatter',w);}
renderDiagram(title,formula,figure+note,'HEALTH EVIDENCE MODEL');}
